import{_ as r,a0 as p,w as i,s as d,I as l,x as o,a1 as e,A as n}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const a=JSON.parse('{"title":"為什麼可以在任何地方工作的開發者們要聚集到世界上最昂貴的城市？ | LCTT x X-CMD","titleTemplate":false,"description":"為什麼可以在任何地方工作的開發者們要聚集到世界上最昂貴的城市？ | LCTT (201707) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"為什麼可以在任何地方工作的開發者們要聚集到世界上最昂貴的城市？ | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"為什麼可以在任何地方工作的開發者們要聚集到世界上最昂貴的城市？ | LCTT (201707) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201707/20170402 Why do developers who could work anywhere flock to the worlds most expensive cities","title":"為什麼可以在任何地方工作的開發者們要聚集到世界上最昂貴的城市？","tag":"201707","desc":""},"relativePath":"201707/20170402 Why do developers who could work anywhere flock to the worlds most expensive cities.md","filePath":"[post].md"}'),u={name:"201707/20170402 Why do developers who could work anywhere flock to the worlds most expensive cities.md"};function m(f,t,w,x,k,T){const s=p("Link");return i(),d("div",null,[t[22]||(t[22]=l("h1",{id:"為什麼可以在任何地方工作的開發者們要聚集到世界上最昂貴的城市",tabindex:"-1"},[o("為什麼可以在任何地方工作的開發者們要聚集到世界上最昂貴的城市？ "),l("a",{class:"header-anchor",href:"#為什麼可以在任何地方工作的開發者們要聚集到世界上最昂貴的城市","aria-label":"Permalink to “為什麼可以在任何地方工作的開發者們要聚集到世界上最昂貴的城市？”"},"​")],-1)),t[23]||(t[23]=l("p",null,[l("img",{src:"https://tctechcrunch2011.files.wordpress.com/2017/04/img_20170401_1835042.jpg?w=977",alt:""})],-1)),l("p",null,[t[1]||(t[1]=o("政治家和經濟學家都在",-1)),e(s,{href:"https://mobile.twitter.com/Noahpinion/status/846054187288866"},{default:n(()=>[...t[0]||(t[0]=[o("哀嚎",-1)])]),_:1}),t[2]||(t[2]=o("某幾個阿爾法地區——舊金山、洛杉磯、紐約、波士頓、多倫多、倫敦、巴黎——在吸引了所有最好的工作的同時變得令人卻步的昂貴，降低了經濟流動性而增大了貧富差異。為什麼那些最好的工作不能搬到其它地區呢？",-1))]),t[24]||(t[24]=l("p",null,"當然，很多工作都不能搬走。工作在紐約或者倫敦（當然，在英國脱歐毀滅倫敦的銀行體系之前）普通的金融從業人員如果告訴他們的老闆他們想要以後在清邁工作，將會在辦公室裏受到嘲笑而且不再受歡迎。",-1)),t[25]||(t[25]=l("p",null,"但是這對（大部分）軟件領域不適用。大部分 web/app 開發者如果這樣要求的話可能會被拒絕；但是它們至少不會被嘲笑或者被炒。優秀開發者往往供不應求，而且我們處在 Skype 和 Slack 的時代，軟件開發完全可以不依賴物質世界的交互。",-1)),t[26]||(t[26]=l("p",null,"（這一切對作家來説更加正確，真的；事實上我是在波納佩發表的這篇文章。但是作家並不像軟件開發者一樣具有足夠的影響力。）",-1)),t[27]||(t[27]=l("p",null,"有些人會告訴你遠程協助的團隊天生比本地團隊效率和生產力低下一些，或者那些“不經意的靈感碰撞”是如此重要以致於每一位員工每天都必須強制到一個地方來人為的製造這樣的碰撞。這些人錯了，有這種問題的團隊只是討論次數不夠多——數量級不過幾次、十幾次或者幾十次，而不是成百上千——也不夠專注。",-1)),l("p",null,[t[4]||(t[4]=o("我知道：在 ",-1)),e(s,{href:"http://happyfuncorp.com/"},{default:n(()=>[...t[3]||(t[3]=[o("HappyFunCorp",-1)])]),_:1}),t[5]||(t[5]=o(" 時，我們廣泛的與遠程團隊工作，而且長期僱傭遠程開發者，而結果難以置信的好。我在我舊金山的家中與斯德哥爾摩、聖保羅、上海、布魯克林、新德里的開發者交流和合作的一天，完全沒有任何不尋常。",-1))]),t[28]||(t[28]=l("p",null,"在這一點上，不管它是不是個好主意，但我有點跑題了。供求關係指出那些擁有足夠技能的開發者可以成為被稱為“數字流浪者”的人，如果他們願意的話。但是許多可以做到的人卻不願意。最近，我在雷克雅維克的一棟通過 Airbnb 共享的房子和一夥不斷變化的臨時遠程工作團隊度過了一段時間，我按照東海岸的時間來跟上他們的工作，也把早上和週末的時光都花費在探索冰島了——但是最後幾乎所有人都回到了灣區生活。",-1)),t[29]||(t[29]=l("p",null,"從經濟層面來説，當然，這太瘋狂了。搬到東南亞工作光在房租一項上每月就會為我們省下幾千美金。 為什麼那些可以在哥斯達黎加掙着舊金山的工資，或者在柏林賺着紐約水平薪資的人們，選擇不這樣做？為什麼那些據説冷靜固執的工程師在財政方面如此荒謬？",-1)),t[30]||(t[30]=l("p",null,"當然這裏有社交和文化原因。清邁很不錯，但沒有大都會博物館或者蒸汽朋克化裝舞會，也沒有 15 分鐘腳程可以到的 50 家美食餐廳。柏林也很可愛，但沒法提供風箏衝浪或者山脈遠足和加州氣候。當然也無法保證擁有無數和你一樣分享同樣價值觀和母語的人們。",-1)),t[31]||(t[31]=l("p",null,"但是我覺得原因除了這些還有很多。我相信相比貧富之間的差異，還有一個更基礎的經濟分水嶺存在。我認為我們在目睹世界上可以實現超凡成就的“極端斯坦（Extremistan）”城市和無法成就偉大但可以工作和賺錢的“平均斯坦（Mediocristan）”城市之間正在生成巨大的裂縫。（這些名詞是從偉大的納西姆·塔勒布那裏偷來的）",-1)),l("p",null,[t[7]||(t[7]=o("（LCTT 譯者注：",-1)),e(s,{href:"http://blog.sina.com.cn/s/blog_5ba3d8610100q3b1.html"},{default:n(()=>[...t[6]||(t[6]=[o("平均斯坦與極端斯坦的概念是美國學者納西姆·塔勒布首先提出來的。他發現在我們所處的世界上，有些事物表現出相當的平均性，大部分個體都靠近均值，離均值越遠則個體數量越稀少，與均值的偏離達到一定程度的個體數量將趨近於零。有些事物則表現出相當的極端性，均值這個概念在這個領域沒有太多的意義，劇烈偏離均值的個體大量存在，而且偏離程度大得驚人。他把前者稱為平均斯坦，把後者稱為極端斯坦。",-1)])]),_:1}),t[8]||(t[8]=o("）",-1))]),t[32]||(t[32]=l("p",null,"藝術行業有着悠久歷史的“極端斯坦”城市。這也解釋了為什麼有抱負的作家紛紛搬到紐約城，而那些已經在國際上大獲成功的導演和演員仍然在不斷被吸引到洛杉磯，如同飛蛾撲火。現在，這對技術行業同樣適用。即使你不曾想試着（幫助）構造一些非凡的事物 —— 如今創業神話如此恢弘，很難想像有工程師完全沒有夢想過它 —— _偉大事物發生的地方_正在以美好的前景如夢如幻的吸引着人們。",-1)),t[33]||(t[33]=l("p",null,"但是關於這一切有趣的是，理論上講，它會改變；因為 —— 直到最近 —— 分佈式的、分散管理的團隊實際上可以獲得超凡的成就。 情況對這些團隊很不利，因為風投的目光趨於短淺。但是沒有任何法律指出獨角獸公司只能誕生在加州和某些屈指可數的次級地域上；而且似乎，不管結果好壞，極端斯坦正在擴散。如果這樣的擴散最終可以矛盾地導致米申地區的房租變_便宜_那就太棒了！",-1)),t[34]||(t[34]=l("hr",null,null,-1)),l("p",null,[t[10]||(t[10]=o("via: ",-1)),e(s,{href:"https://techcrunch.com/2017/04/02/why-do-developers-who-could-work-anywhere-flock-to-the-worlds-most-expensive-cities/"},{default:n(()=>[...t[9]||(t[9]=[o("https://techcrunch.com/2017/04/02/why-do-developers-who-could-work-anywhere-flock-to-the-worlds-most-expensive-cities/",-1)])]),_:1})]),l("p",null,[t[14]||(t[14]=o("作者：",-1)),e(s,{href:"https://techcrunch.com/author/jon-evans/"},{default:n(()=>[...t[11]||(t[11]=[o("Jon Evans",-1)])]),_:1}),t[15]||(t[15]=o(" 譯者：",-1)),e(s,{href:"https://github.com/xiaow6"},{default:n(()=>[...t[12]||(t[12]=[o("xiaow6",-1)])]),_:1}),t[16]||(t[16]=o(" 校對：",-1)),e(s,{href:"https://github.com/wxy"},{default:n(()=>[...t[13]||(t[13]=[o("wxy",-1)])]),_:1})]),l("p",null,[t[19]||(t[19]=o("本文由 ",-1)),e(s,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...t[17]||(t[17]=[o("LCTT",-1)])]),_:1}),t[20]||(t[20]=o(" 原創編譯，",-1)),e(s,{href:"https://linux.cn/"},{default:n(()=>[...t[18]||(t[18]=[o("Linux中國",-1)])]),_:1}),t[21]||(t[21]=o(" 榮譽推出",-1))])])}const C=r(u,[["render",m]]);export{a as __pageData,C as default};
